text:
// Pawn Champ - The Dead Letter Office. Major quest M23, batch G (docs/quests/MAJOR.md#m23-the-dead-letter-office).
// The post office is closing. The retiring postmistress pawns her stamp album, and in it is a
// block of the 1930 schooner stamp printed upside down. The rest of the sheet is still in the
// building, hidden there in 1930 by the postmaster who stole it.
//
// Hook (W1 Wed)              Winifred Paine sells her stamp album. The loupe finds the inverts.
// Middle (W2 Mon, Tue, Wed)  Anselm Hart the dealer, then the postal inspector, then Winifred again
//                            with the keys and the story of Horace Pettibone.
// Scene 1 (W2 Wed-W3 Tue)    the post office after hours: the dead-letter room, and case nine.
// Scene 2 (W3 Mon-Thu)       the ferry landing at dawn: Anselm's forgeries, and his offer.
// Finale (W3 Thu-W4 Thu)     the last day: the sorting case comes off the wall.
// Crossings: undelivered letters for Hollis Fenn (M1), Royce Kittredge (M9) and the Breakwaters
// (M12), delivered if their quest is in the run.
//
// Written as data: docs/STORY_DATA.md. Strict JSON inside the call.
defineStory({
  "id": "dead",
  "kind": "major",
  "colour": "#3b6fd0",
  "family": "crime",
  "title": "The Dead Letter Office",
  "crosses": ["hollis", "radio", "breakwaters"],
  "rumour": "The post office is closing for good, and Winifred Paine is selling up.",
  "endings": { "anselm": "Sold to the Dealer", "inspector": "Federal Property", "auction": "Winifred's Retirement", "swap": "Upside Down" },
  "icons": {
    "stamps": [
      "............",
      ".kkkkkkkkkk.",
      ".kcScScScSk.",
      ".kSbbbbbbck.",
      ".kcbBccBbSk.",
      ".kSbBccBbck.",
      ".kcbbwwbbSk.",
      ".kSbbwwbbck.",
      ".kcbbbbbbSk.",
      ".kScScScSck.",
      ".kkkkkkkkkk.",
      "............"
    ]
  },
  "cast": {
    "winifred": {
      "name": "Winifred Paine",
      "look": { "skin": "#f0d0b8", "hair": "#d8d8e0", "hs": 3, "coat": "#3a4a7a", "trim": "#c83a2a", "style": "jacket", "long": true, "pants": "#2a2a3a", "glasses": "#2a2a2e", "bag": "#5a3a2a" }
    },
    "anselm": {
      "name": "Anselm Hart",
      "look": { "skin": "#e8c8a8", "hair": "#c8a060", "hs": 1, "coat": "#8a6a3a", "trim": "#e8e0c8", "style": "suit", "pants": "#5a4a32", "glasses": "#c8a050", "hat": "wide", "hatc": "#5a4a3a", "band": "#2a2a2a" }
    },
    "calloway": {
      "name": "Inspector Dana Calloway",
      "look": { "skin": "#8a5a3a", "hair": "#1a1410", "hs": 0, "coat": "#2a2a32", "trim": "#e8e4dc", "style": "suit", "pants": "#2a2a32", "bag": "#1a1a1e" }
    }
  },
  "uniques": {
    "stampAlbum": {
      "name": "Winifred's stamp album",
      "icon": "stamps",
      "cat": "curio",
      "guide": 40,
      "condLabel": "Forty-one years of it",
      "questKey": true,
      "tells": [
        "Mostly ordinary: lighthouses, flags, the moon landing. Mounted with real care.",
        { "text": "On the last page, a block of four 1930 Hollow Neck schooner stamps. The schooner is upside down on all four.", "cls": "good" }
      ]
    },
    "invertSheet": {
      "name": "The 1930 schooner sheet (inverted)",
      "icon": "stamps",
      "cat": "curio",
      "guide": 0,
      "condLabel": "Ninety-six stamps",
      "questKey": true,
      "tells": [
        "Ninety-six schooners, all sailing upside down. Wrapped in a 1930 copy of the Clarion.",
        "Pencilled on the wrapper: \"H.P. Not mine to keep. Not mine to give back.\""
      ]
    },
    "anselmFakes": {
      "name": "Anselm's schooner block",
      "icon": "stamps",
      "cat": "curio",
      "guide": 400,
      "fake": true,
      "condLabel": "Suspiciously crisp",
      "tells": [
        "The perforations are a fraction too even, and the paper glows a little under your lamp. Modern stock."
      ]
    }
  },
  "about": [
    "A crime story about the post office closing. Winifred Paine, postmistress for forty-one years, sells you her stamp album (§{winifredAlbum}). On the last page are four 1930 schooner stamps printed upside down, a sheet that was meant to be burned. Anselm Hart, a Worcester dealer, offers $300 for the album (§{anselmCalls}), and Inspector Calloway of the Postal Inspection Service says any such sheet belongs to the United States (§{callowayCalls}). Selling to either ends it there.",
    "Winifred comes back (§{winifredKeys}): her old postmaster gave her the four in 1984 and said the rest was \"where the letters go to wait\". After hours at the post office (§{deadOffice}) you find old undelivered letters you can deliver yourself, some tied to other stories in the run, and sorting case nine, bolted to the wall until the movers come.",
    "Hart meets you at the ferry landing with a block of his own forgeries and a plan: swap them for the real sheet and pay you $900 (§{deadSwap}). You can take them, refuse, or tell the inspector.",
    "On the last day (§{deadLast}) the whole sheet of ninety-six is behind case nine. Hand it to the inspector (Federal Property); get it auctioned for Winifred's retirement (Winifred's Retirement); sell it to Hart for $600 (Sold to the Dealer); or give the inspector the forgeries and sell Hart the real one (Upside Down)."
  ],
  "notes": "Anselm's forgeries are fakes: selling one is like selling any fake. If you never used them, he doesn't come back for them.",
  "scenes": {
    "winifredAlbum": {
      "title": "Winifred Paine sells her stamp album",
      "customer": "winifred",
      "steps": [
        {
          "say": "winifred",
          "text": [
            "Winifred Paine. I've been the post office for forty-one years. On the twentieth it becomes a drop box outside the pharmacy.",
            "I'm going to my sister's in Fall River, and the move costs what moves cost. This is my album. Mostly the usual. I'd take sixty."
          ]
        },
        { "offer": { "unique": "stampAlbum" }, "persona": "honest", "asking": 60, "min": 40 },
        {
          "if": "offer != 'deal'",
          "then": [
            { "set": { "deadOut": true } },
            { "say": "winifred", "text": "No, I suppose stamps are a hard sell these days. Everyone just texts." },
            { "leave": "winifred" },
            { "end": true }
          ]
        },
        { "set": { "deadIn": true } },
        { "say": "winifred", "text": "Mind the last page. Those are the only stamps I ever bought for myself. I never had the nerve to ask what they were worth." },
        { "leave": "winifred" },
        { "find": "album", "in": "stock", "match": { "uniqueId": "stampAlbum", "inspected": false } },
        { "narrate": "You turn to the last page. Four little blue stamps, a schooner on a green sea. The schooner is upside down on every one.", "if": "album" },
        { "toast": "The 1930 schooner, printed upside down. Somebody, somewhere, will want this very much.", "icon": "stamps" }
      ]
    },
    "anselmCalls": {
      "title": "Anselm Hart wants the last page",
      "customer": "anselm",
      "steps": [
        {
          "say": "anselm",
          "text": [
            "Anselm Hart, philatelist, of Hart & Daughter, Worcester. There is no daughter. It looks better on the card.",
            "Small towns talk, and post offices talk most of all. You have Winifred Paine's album. I would like the last page.",
            "Three hundred dollars, cash, now, and we never speak of it again. It's a very good price for four little stamps."
          ]
        },
        {
          "choose": [
            {
              "label": "Sell him the album",
              "hint": "(+$300; the story ends here)",
              "then": [
                { "find": "album", "in": "stock", "match": { "uniqueId": "stampAlbum" } },
                { "take": "album" },
                { "coin": 300, "why": "Sold Winifred's album to Anselm Hart" },
                { "set": { "deadEnd": "anselm", "deadDone": true } },
                { "say": "anselm", "text": "A pleasure. Do give Mrs. Paine my regards. Or rather, don't." },
                { "leave": "anselm" },
                { "end": true }
              ]
            },
            { "label": "\"Not yet.\"" },
            {
              "label": "\"What makes them worth that?\"",
              "then": [
                {
                  "say": "anselm",
                  "text": [
                    "In 1930 a sheet of ninety-six went through the press upside down. The Post Office Department destroyed it. Officially.",
                    "Four have come to light since. All four are in front of you. Which makes me wonder where the other ninety-two went."
                  ]
                }
              ]
            }
          ]
        },
        { "say": "anselm", "text": "Then I'll stay in town a while. The ferry landing does a decent coffee at six. I'm always there." },
        { "leave": "anselm" }
      ]
    },
    "callowayCalls": {
      "title": "The postal inspector",
      "customer": "calloway",
      "steps": [
        {
          "say": "calloway",
          "text": [
            "Inspector Calloway, Postal Inspection Service. The real kind, with a badge.",
            "I go to every office the week it closes. Mostly it's paperclips. This time there are stories about a misprinted sheet, and a dealer from Worcester asking about it.",
            "If a misprint from 1930 turned up, it was never sold. It was stolen. It belongs to the United States."
          ]
        },
        {
          "choose": [
            {
              "label": "Hand her the album",
              "hint": "(heat -8; the story ends here)",
              "then": [
                { "find": "album", "in": "stock", "match": { "uniqueId": "stampAlbum" } },
                { "take": "album" },
                { "heat": -8 },
                { "set": { "deadEnd": "inspector", "deadDone": true } },
                { "say": "calloway", "text": "Thank you. Mrs. Paine won't be in any trouble. I'll see that she isn't." },
                { "leave": "calloway" },
                { "end": true }
              ]
            },
            { "label": "\"I'll let you know if I hear anything.\"" }
          ]
        },
        { "say": "calloway", "text": "Please do. I'm in town until the doors close for good." },
        { "leave": "calloway" }
      ]
    },
    "winifredKeys": {
      "title": "Winifred comes back with her keys",
      "customer": "winifred",
      "steps": [
        {
          "say": "winifred",
          "text": [
            "An inspector has been at my counter, and a man in a hat has been at my window. I know what I sold you. I think I always did.",
            "My first postmaster was Horace Pettibone. In 1930 the schooner sheet came up from Boston upside down, and he was meant to send it back for burning.",
            "He gave me those four as a wedding present in 1984, the week before he died. He said, \"The rest is where the letters go to wait.\" I never knew what he meant.",
            "I still have my keys until the twentieth. If you want to look, come after closing. I'll hold the flashlight. I'm not going in there alone."
          ]
        },
        { "set": { "deadKeys": true } },
        { "toast": "Calendar: the post office, after hours", "look": "winifred" },
        { "leave": "winifred" }
      ]
    },
    "deadOffice": {
      "title": "The post office after hours",
      "steps": [
        {
          "stage": "postoffice",
          "actors": [
            { "id": "you", "cast": "keeper", "name": "You", "at": [120, 166] },
            { "id": "winifred", "cast": "winifred", "at": [150, 164] }
          ]
        },
        { "narrate": "The post office after closing. The exit sign, the brass grille, a wall of little boxes with little dials, and Winifred's flashlight finding the pigeonholes one at a time." },
        { "say": "winifred", "text": "\"Where the letters go to wait.\" That's the dead-letter room. Letters with no address we could read, and no return. We keep them a year. Some of these are older than me." },
        { "walk": "winifred", "to": [236, 160] },
        { "narrate": "A canvas sack and a shelf of shoeboxes. Most of the letters are faded past reading. A few aren't." },
        { "narrate": "To \"Pell, the boat yard, Hollow Neck\", 1971, from Portsmouth. His sister's handwriting, Winifred thinks." },
        { "narrate": "To Hollis Fenn, Customs House, 2019: a letter from Boston saying he got the promotion. Somebody sent it to the wrong building.", "if": "quest.hollis" },
        { "narrate": "To \"R.K., Gannet Island\", 1993, no stamp. Two words: \"I know.\" Signed with a D.", "if": "quest.radio" },
        { "narrate": "To \"The Breakwaters (the band)\", 1994: a record label in New York wants a demo. It never arrived.", "if": "quest.breakwaters" },
        {
          "choose": [
            {
              "label": "Take the letters and deliver them yourself",
              "then": [
                { "hook": "deliverLetters", "note": "remembers who got a letter (Old Pell, and Hollis, Royce and the Breakwaters if their stories are in the run), and +2 reputation a letter" },
                { "say": "winifred", "text": "Thirty, forty, fifty years late. That's still delivered. That counts." }
              ]
            },
            { "label": "Leave them for the inspector" }
          ]
        },
        { "walk": "winifred", "to": [270, 160] },
        { "narrate": "On the way out, Winifred's light crosses the sorting case. Ninety-six pigeonholes. The ninth from the bottom has a brass plate where the others have paper labels, and four screws nobody has turned since the Depression." },
        { "say": "winifred", "text": "Case nine. It's bolted through to the wall. The movers take it down on the last day, and not before. Horace, you old devil." },
        { "set": { "deadClue": true } },
        { "toast": "Calendar: the last day at the post office", "look": "winifred" }
      ]
    },
    "deadSwap": {
      "title": "Coffee with Anselm Hart at the ferry landing",
      "steps": [
        {
          "stage": "ferryLanding",
          "actors": [
            { "id": "you", "cast": "keeper", "name": "You", "at": [120, 164] },
            { "id": "anselm", "cast": "anselm", "at": [196, 160], "facingLeft": true }
          ]
        },
        { "narrate": "The ferry landing at six. Anselm Hart is exactly where he said he'd be, with two coffees, one of them for you." },
        {
          "say": "anselm",
          "text": [
            "You've been in the building. Don't look like that, everyone saw. The rest of the sheet is in there, and it comes out on the last day.",
            "Here's a better idea than selling it. These are mine. My own work."
          ]
        },
        { "narrate": "He opens a glassine envelope. A block of four upside-down schooners, perfect, a little too perfect." },
        { "say": "anselm", "text": "On the last day, the real sheet goes in my case and a sheet of these goes to the inspector. She finds what she's looking for and goes home. I pay you nine hundred. Winifred gets her move paid, privately, from me. Everyone is happy." },
        {
          "choose": [
            {
              "label": "Take his forgeries, and think about it",
              "then": [
                { "set": { "deadSwap": true } },
                {
                  "if": "shelf.free",
                  "then": [{ "add": { "unique": "anselmFakes" } }, { "refresh": "panel" }]
                },
                { "say": "anselm", "text": "Think as long as you like. Until the last day." }
              ]
            },
            {
              "label": "\"No.\"",
              "then": [
                { "say": "anselm", "text": "Pity. Then I'll simply be there with my chequebook like everyone else." }
              ]
            },
            {
              "label": "Tell Inspector Calloway about him",
              "hint": "(heat -6)",
              "then": [
                { "set": { "deadTold": true } },
                { "heat": -6, "why": "Told the postal inspector about Anselm Hart" },
                { "say": "anselm", "text": "Ah. Well. I'll finish my coffee, then. I suspect it's the last I'll have in this town." }
              ]
            }
          ]
        }
      ]
    },
    "deadLast": {
      "title": "The last day at the post office",
      "steps": [
        {
          "stage": "postofficeLast",
          "actors": [
            { "id": "you", "cast": "keeper", "name": "You", "at": [110, 166] },
            { "id": "winifred", "cast": "winifred", "at": [140, 164] },
            { "id": "calloway", "cast": "calloway", "at": [250, 160], "facingLeft": true }
          ]
        },
        { "narrate": "The last day. Morning light in a room with nothing left in it but boxes. The sorting case is down, and where it hung there's a pale rectangle and a brass plate." },
        { "say": "winifred", "text": "They took case nine off at eight o'clock. I asked them to leave the back plate for me. For sentimental reasons. I've never had sentimental reasons in my life." },
        { "narrate": "Behind the plate, in a flat tin, wrapped in a 1930 Clarion: ninety-six schooners sailing upside down. Pencilled on the paper: \"H.P. Not mine to keep. Not mine to give back.\"" },
        { "add": { "unique": "invertSheet" }, "as": "sheet" },
        { "refresh": "panel" },
        { "say": "calloway", "text": "And there it is. I'll need that, keeper. Or I'll need a very good reason not to have it." },
        { "find": "fakes", "in": "stock", "match": { "uniqueId": "anselmFakes" } },
        {
          "choose": [
            {
              "label": "Hand the sheet to Inspector Calloway",
              "hint": "(heat -10, rep +6)",
              "then": [
                { "take": "sheet" },
                { "heat": -10 },
                { "rep": 6, "why": "Returned the 1930 sheet" },
                { "say": "calloway", "text": "Thank you. It goes to the Postal Museum, and Horace Pettibone becomes a footnote. Mrs. Paine keeps her four. I never saw them." },
                { "set": { "deadEnd": "inspector" } }
              ]
            },
            {
              "label": "Ask her to let it be auctioned for Winifred",
              "hint": "(rep +8, a $100 finder's fee)",
              "then": [
                { "take": "sheet" },
                { "say": "calloway", "text": "It isn't mine to give. But a misprint can be \"released\" to the finder by the Department, once, if the finder has given the service sixty years... Mrs. Paine, how long have you worked here?" },
                { "say": "winifred", "text": "Forty-one years. Sixty, if you count the Saturdays twice." },
                { "say": "calloway", "text": "I'll count them twice." },
                { "rep": 8, "why": "Got the schooner sheet auctioned for Winifred" },
                { "coin": 100, "why": "Finder's fee from the schooner auction" },
                { "set": { "deadEnd": "auction" } }
              ]
            },
            {
              "label": "Sell it to Anselm Hart",
              "hint": "(+$600; Winifred reads about it in the paper)",
              "then": [
                { "take": "sheet" },
                { "remove": "calloway" },
                { "enter": { "id": "anselm", "cast": "anselm", "at": [250, 160], "facingLeft": true } },
                { "say": "anselm", "text": "Six hundred, as promised. The inspector was called away. Something about a drop box outside the pharmacy." },
                { "coin": 600, "why": "Sold the schooner sheet to Anselm Hart" },
                { "say": "winifred", "text": "I see. Well. It was never mine either." },
                { "set": { "deadEnd": "anselm" } }
              ]
            },
            {
              "label": "Give her Anselm's forgeries, and sell him the real sheet",
              "hint": "(+$900, heat +12)",
              "if": "flag.deadSwap && fakes",
              "then": [
                { "take": "sheet" },
                { "take": "fakes" },
                { "narrate": "You hand the inspector a sheet that is perfect, a little too perfect. She holds it up to the window, frowns, and signs for it." },
                { "coin": 900, "why": "Anselm Hart paid for the real sheet" },
                { "heat": 12 },
                { "set": { "deadEnd": "swap" } }
              ]
            }
          ]
        },
        { "refresh": "panel" },
        { "set": { "deadDone": true } }
      ]
    }
  },
  "beats": [
    { "at": "1-3", "cast": "winifred", "scene": "winifredAlbum" },
    { "at": "2-1", "cast": "anselm", "scene": "anselmCalls", "if": "flag.deadIn && !flag.deadDone && hook.albumHere" },
    { "at": "2-2", "cast": "calloway", "scene": "callowayCalls", "if": "flag.deadIn && !flag.deadDone && hook.albumHere" },
    { "at": "2-3", "cast": "winifred", "scene": "winifredKeys", "if": "flag.deadIn && !flag.deadDone" }
  ],
  "nights": [
    {
      "id": "dead-office",
      "window": ["2-3", "3-2"],
      "if": "flag.deadKeys && !flag.deadDone",
      "scene": "deadOffice",
      "test": [{ "set": { "deadKeys": true } }]
    },
    {
      "id": "dead-swap",
      "window": ["3-1", "3-4"],
      "if": "flag.deadClue && !flag.deadDone",
      "scene": "deadSwap",
      "test": [{ "set": { "deadClue": true } }]
    },
    {
      "id": "dead-last",
      "window": ["3-4", "4-4"],
      "if": "flag.deadClue && !flag.deadDone",
      "scene": "deadLast",
      "test": [{ "set": { "deadClue": true, "deadSwap": true } }, { "add": { "unique": "anselmFakes" } }]
    }
  ],
  "calendar": [
    { "id": "dead-office", "night": "dead-office", "story": "dead", "where": "The post office", "title": "Winifred's keys", "known": "flag.deadKeys", "scene": "deadOffice" },
    { "id": "dead-swap", "night": "dead-swap", "story": "dead", "where": "The ferry landing", "title": "Coffee with Anselm Hart", "known": "flag.deadClue", "scene": "deadSwap" },
    { "id": "dead-last", "night": "dead-last", "story": "dead", "where": "The post office", "title": "The last day", "known": "flag.deadClue", "scene": "deadLast" }
  ],
  "epilogue": [
    { "line": "The schooner sheet sold in Boston for a sum the Clarion printed in a very large font. Winifred Paine bought her sister's house outright.", "if": "flag.deadEnd == 'auction'" },
    { "line": "The schooner sheet is in a glass case at the Postal Museum. The label calls Horace Pettibone \"a conscientious official\". Winifred laughed out loud.", "if": "flag.deadEnd == 'inspector'" },
    { "line": "Anselm Hart sold the schooners one at a time, for years. Winifred Paine sends you a Christmas card from Fall River anyway, with a very ordinary stamp.", "if": "flag.deadEnd == 'anselm'" },
    { "line": "The Postal Museum displays a sheet of ninety-six upside-down schooners. Under ultraviolet light it would glow. Nobody has checked.", "if": "flag.deadEnd == 'swap'" },
    {
      "line": { "if": "flag.deadLetters.count == 1", "then": "You delivered a letter from the dead-letter room, decades late. Nobody complained about the delay.", "else": "You delivered {flag.deadLetters.count} letters from the dead-letter room, decades late. Nobody complained about the delay." },
      "if": "flag.deadLetters.count > 0"
    }
  ],
  "outcome": "flag.deadEnd"
});
